  ('c6e5de02-9b66-4503-b37c-9236dc65b1b8', $$Wiskunde A$$, $$HAVO$$, $$Appels met peren vergelijken$$, $$HAVO Wiskunde A 2024-II$$),
  ('f81929e4-074d-45f4-9b8e-ba91c6a13168', $$Wiskunde A$$, $$HAVO$$, $$Vangen-hervangen$$, $$HAVO Wiskunde A 2024-II$$),
