insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('babfb5f4-159b-4fc2-b121-631ab39b07e8', 'c6e5de02-9b66-4503-b37c-9236dc65b1b8', $$inleiding: oogstraming$$,
   $$wiskunde-a-havo-2024-ii-appels-met-peren-vergelijken-context1.png$$,
   $$In figuur 1 staat een bericht dat op internet te lezen was over de appel- en perenoogst in Nederland. Hierin wordt gesproken over de oogstraming van 2021; dit is de schatting van de oogstopbrengst (in miljoen kilo) van dat jaar.$$, 'inline'),
  ('fb94c564-53a7-4bdf-be2b-b3eb82b7b706', 'c6e5de02-9b66-4503-b37c-9236dc65b1b8', $$figuur 1: bericht oogstraming 2021$$,
   $$wiskunde-a-havo-2024-ii-appels-met-peren-vergelijken-context2.png$$,
   $$figuur 1
Meer appels en minder peren verwacht dan vorig jaar Geplaatst op 27 juli 2021
Dit jaar zullen in Nederland naar verwachting meer appels worden geplukt dan vorig jaar, terwijl de totale perenoogst lager wordt geraamd dan vorig jaar. De Nederlandse oogstraming komt uit op 250 miljoen kilo appels en 325 miljoen kilo peren. Dit blijkt uit informatie van GroentenFruit Huis en NFO.
Er hangen meer appels aan de bomen dan in 2020. Hierdoor wordt de totale appeloogst (in miljoen kilo) 14 procent hoger ingeschat dan in 2020. Bij peren is het beeld juist andersom waardoor de perenoogst (in miljoen kilo) 19 procent lager wordt geraamd dan vorig jaar.$$, 'inline'),
  ('215b4681-a685-4612-8214-8c7f452ea88c', 'c6e5de02-9b66-4503-b37c-9236dc65b1b8', $$gemiddeld gewicht appel en peer$$,
   $$wiskunde-a-havo-2024-ii-appels-met-peren-vergelijken-context3.png$$,
   $$Neem aan dat een appel gemiddeld 150 gram weegt en een peer gemiddeld 225 gram. Op basis van de oogstraming kun je het geschatte aantal appels en het geschatte aantal peren in 2021 berekenen.$$, 'inline'),
  ('cc643190-5340-4277-b077-9d942cea4cbf', 'c6e5de02-9b66-4503-b37c-9236dc65b1b8', $$totale gewicht in 2020$$,
   $$wiskunde-a-havo-2024-ii-appels-met-peren-vergelijken-context4.png$$,
   $$Op basis van het bericht kun je het totale gewicht berekenen dat in 2020 aan appels en peren samen is geoogst.$$, 'inline'),
  ('a1485707-a9a8-46f2-a6c7-ad7682f08e8a', 'c6e5de02-9b66-4503-b37c-9236dc65b1b8', $$figuur 2: inleiding$$,
   $$wiskunde-a-havo-2024-ii-appels-met-peren-vergelijken-context5.png$$,
   $$In figuur 2 zie je voor de periode 2000-2010 het totaalgewicht aan peren dat in Nederland is geoogst. Ook zie je de oppervlakte waarop deze peren werden geteeld. Neem aan dat deze oppervlakte gedurende een kalenderjaar gelijk blijft.$$, 'inline'),
  ('cf225ee3-ab4c-4a8e-9b1a-1938ef4f4a30', 'c6e5de02-9b66-4503-b37c-9236dc65b1b8', $$figuur 2: perenteelt$$,
   $$wiskunde-a-havo-2024-ii-appels-met-peren-vergelijken-context6.png$$,
   $$figuur 2 perenteelt
perenteeltoppervlakte (hectare) | oogst (miljoen kg) | jaar (2000 – 2010)
Legenda: perenteeltoppervlakte, oogst$$, 'inline'),
  ('c06cea1a-9fea-4dc2-ab83-443426a6407a', 'c6e5de02-9b66-4503-b37c-9236dc65b1b8', $$formule perenteeltoppervlakte$$,
   $$wiskunde-a-havo-2024-ii-appels-met-peren-vergelijken-context7.png$$,
   $$De perenteeltoppervlakte neemt in de periode van 2000 tot en met 2015 lineair toe. We kunnen voor die periode de perenteeltoppervlakte beschrijven met de volgende formule:
Tₚ = 6000 + 200t
Hierin is Tₚ de perenteeltoppervlakte in hectare en t het aantal gehele jaren na 2000.$$, 'inline'),
  ('573ae60e-89ee-4a9b-86cd-d397e54bbee2', 'c6e5de02-9b66-4503-b37c-9236dc65b1b8', $$tabel: appelteeltoppervlakte$$,
   $$wiskunde-a-havo-2024-ii-appels-met-peren-vergelijken-context8.png$$,
   $$In de tabel staat de appelteeltoppervlakte in 2003 en 2015.
tabel
jaar | 2003 | 2015
appelteeltoppervlakte Tₐ (in hectare) | 10 296 | 7600
Ga ervan uit dat de appelteeltoppervlakte in de periode 2000-2015 lineair afneemt en dat deze oppervlakte gedurende een kalenderjaar steeds gelijk blijft.$$, 'inline'),
  ('bf82310e-0572-44ab-aed2-fb877247cfa4', 'c6e5de02-9b66-4503-b37c-9236dc65b1b8', $$exponentiële afname na 2015$$,
   $$wiskunde-a-havo-2024-ii-appels-met-peren-vergelijken-context9.png$$,
   $$Men verwachtte dat na 2015 de appelteeltoppervlakte exponentieel zou afnemen met 19,4% per vijf jaar.$$, 'inline'),
  ('4620c85e-9bd8-415f-8231-f1a7fe686eda', 'f81929e4-074d-45f4-9b8e-ba91c6a13168', $$inleiding: techniek vangen-hervangen$$,
   $$wiskunde-a-havo-2024-ii-vangen-hervangen-context1.png$$,
   $$Het is niet eenvoudig het totaal aantal vissen in een meer te tellen. Met behulp van de statistische techniek ‘vangen-hervangen’ is het mogelijk een schatting te doen van het aantal vissen. Deze techniek werkt als volgt:$$, 'inline'),
  ('41ec3591-d9da-4776-a9b2-630f282c0e8e', 'f81929e4-074d-45f4-9b8e-ba91c6a13168', $$eerste steekproef$$,
   $$wiskunde-a-havo-2024-ii-vangen-hervangen-context2.png$$,
   $$Vang een aantal vissen uit het meer. Dit is de eerste steekproef. Geef deze vissen een merkteken. Zie figuur 1.$$, 'inline'),
  ('3fed0c47-f58e-4219-83ce-f7d126fc632a', 'f81929e4-074d-45f4-9b8e-ba91c6a13168', $$figuur 1$$,
   $$wiskunde-a-havo-2024-ii-vangen-hervangen-context3.png$$,
   $$figuur 1$$, 'inline'),
  ('e831cab8-afd1-467a-b3d0-d052796bc833', 'f81929e4-074d-45f4-9b8e-ba91c6a13168', $$tweede steekproef$$,
   $$wiskunde-a-havo-2024-ii-vangen-hervangen-context4.png$$,
   $$Zet de gemerkte vissen vervolgens weer terug in het meer. Wacht een tijdje tot de gemerkte vissen zich over het hele meer verspreid hebben en vang nogmaals een aantal vissen uit het meer. Dit is de tweede steekproef. Zie figuur 2.$$, 'inline'),
  ('59e12405-79d7-4f61-b605-03f0e057ebb2', 'f81929e4-074d-45f4-9b8e-ba91c6a13168', $$figuur 2$$,
   $$wiskunde-a-havo-2024-ii-vangen-hervangen-context5.png$$,
   $$figuur 2$$, 'inline'),
  ('6e2bfb47-0c91-4ec2-bc2a-1ffb667f2027', 'f81929e4-074d-45f4-9b8e-ba91c6a13168', $$proportie gemerkte vissen$$,
   $$wiskunde-a-havo-2024-ii-vangen-hervangen-context6.png$$,
   $$We kunnen nu veronderstellen dat de proportie gemerkte vissen in de tweede steekproef, gelijk is aan de proportie gemerkte vissen in het hele meer. In formulevorm:$$, 'inline'),
  ('8d9817b5-7440-4760-9283-95d1e6dda3de', 'f81929e4-074d-45f4-9b8e-ba91c6a13168', $$formule 1$$,
   $$wiskunde-a-havo-2024-ii-vangen-hervangen-context7.png$$,
   $$R/C = M/N (formule 1)$$, 'inline'),
  ('1408b486-ac08-4d3c-98da-8582cd5cb2e8', 'f81929e4-074d-45f4-9b8e-ba91c6a13168', $$betekenis R, C, M en N$$,
   $$wiskunde-a-havo-2024-ii-vangen-hervangen-context8.png$$,
   $$Hierbij is:
− R het aantal gemerkte vissen in de tweede steekproef;
− C het aantal gevangen vissen dat in de tweede steekproef;
− M het aantal gevangen, en dus gemerkte, vissen in de eerste steekproef;
− N het (geschatte) aantal vissen in het meer.$$, 'inline'),
  ('4dd8289f-274e-4d19-8421-28ade2d4a829', 'f81929e4-074d-45f4-9b8e-ba91c6a13168', $$steekproeven: 80 gemerkt, 6 en 92$$,
   $$wiskunde-a-havo-2024-ii-vangen-hervangen-context9.png$$,
   $$Biologen vangen in een meer bij een eerste steekproef 80 vissen, merken deze en zetten ze weer terug in het meer. Een paar dagen later wordt een tweede steekproef vissen gevangen. Hierin bevinden zich 6 gemerkte en 92 ongemerkte vissen.$$, 'inline'),
  ('440f71ed-4e18-4a26-bf76-1bc16c0ed893', 'f81929e4-074d-45f4-9b8e-ba91c6a13168', $$herleiding naar formule 2$$,
   $$wiskunde-a-havo-2024-ii-vangen-hervangen-context10.png$$,
   $$We kunnen formule 1 herleiden tot een formule waarmee je eenvoudiger het aantal vissen N in het meer kunt berekenen:$$, 'inline'),
  ('f027f0fd-d4ea-4b0c-891b-ae4bade9ae9f', 'f81929e4-074d-45f4-9b8e-ba91c6a13168', $$formule 2 en steekproeven Adri en Fiona$$,
   $$wiskunde-a-havo-2024-ii-vangen-hervangen-context11.png$$,
   $$N = M·C/R (formule 2)
Biologen Adri en Fiona vangen samen een eerste steekproef, waarna zij alle 30 vissen merken die ze samen hebben gevangen. De gemerkte vissen zetten ze terug in het meer. Om de betrouwbaarheid van de schatting van het aantal vissen in het meer te vergroten, vangt elk van hen 180 vissen als tweede steekproef. Eerst vangt Adri 180 vissen en hij telt het aantal gemerkte vissen. Daarna zet hij de 180 vissen terug in het meer. Vervolgens vangt Fiona 180 vissen. In de steekproef van Fiona is er één vis meer gemerkt dan in de steekproef van Adri. Beiden berekenen met formule 2 het aantal vissen in het meer. Fiona’s uitkomst blijkt 60 lager te zijn dan Adri’s uitkomst.$$, 'inline'),
  ('b74349d7-9e0c-4807-b5c3-de6033d9f995', 'f81929e4-074d-45f4-9b8e-ba91c6a13168', $$situatie waarin schatten niet lukt$$,
   $$wiskunde-a-havo-2024-ii-vangen-hervangen-context12.png$$,
   $$Er is een situatie mogelijk, waarbij je vissen in de eerste steekproef vangt en merkt, in een tweede steekproef weer vissen vangt, maar dat het niet lukt om met formule 1 of 2 het aantal vissen in het meer te schatten.$$, 'inline'),
  ('2db3f9d7-2fac-4e4e-8ff2-1a51d4c5a99a', 'f81929e4-074d-45f4-9b8e-ba91c6a13168', $$formule 3 en situatie 120 en 150$$,
   $$wiskunde-a-havo-2024-ii-vangen-hervangen-context13.png$$,
   $$Formule 1 en 2 werken in de praktijk minder goed als R klein is. Daarom is er met computersimulaties gezocht naar een formule die betere schattingen geeft. Uit die computersimulaties bleek dat bij kleine waarden van R, onderstaande formule betere schattingen geeft voor het aantal vissen in het meer dan formule 2.
N = (M+1)·(C+1)/R − 1 (formule 3)
Het verschil in de schattingen van het aantal vissen volgens de formules 2 en 3 wordt groter naarmate er minder gemerkte vissen in een tweede steekproef worden gevangen.
We bekijken de situatie waarbij in de eerste steekproef 120 vissen zijn gevangen en gemerkt en in een tweede steekproef 150 vissen zijn gevangen.$$, 'inline'),
  ('9172e2e2-f4e3-406b-b11e-e280e99cd2ff', 'fff4b3ba-e78d-4e35-b469-60620a2ea4c3', $$inleiding: drie onderzoeken$$,
   $$wiskunde-a-havo-2024-ii-hygiene-op-school-context1.png$$,
   $$In 2018 verschenen er berichten in de media over de (toilet)hygiëne op Nederlandse basisscholen en middelbare scholen. De berichten waren gebaseerd op drie onderzoeken onder respectievelijk leraren die werkzaam waren binnen het basis- of voortgezet onderwijs, leerlingen tussen de 5 en 16 jaar oud en ouders met een kind tussen de 5 en 16 jaar oud. In totaal namen 630 leraren, 452 leerlingen en 626 ouders deel aan het onderzoek. We nemen aan dat elk van de drie steekproeven aselect en representatief was.$$, 'inline'),
  ('bd3a54b4-a783-4952-9409-df240ee5ea9b', 'fff4b3ba-e78d-4e35-b469-60620a2ea4c3', $$194 van de 452 leerlingen$$,
   $$wiskunde-a-havo-2024-ii-hygiene-op-school-context2.png$$,
   $$In de steekproef van de leerlingen gaven 194 van de 452 leerlingen aan regelmatig moeite te hebben met opletten tijdens de les, omdat zij op sommige momenten naar het toilet moeten, maar niet gaan.$$, 'inline'),
  ('7f479665-a33a-48c2-a415-b69bf11b9d44', 'fff4b3ba-e78d-4e35-b469-60620a2ea4c3', $$basisschool en middelbare school$$,
   $$wiskunde-a-havo-2024-ii-hygiene-op-school-context3.png$$,
   $$Van de 452 leerlingen in de steekproef zaten er 302 op de basisschool en 150 op de middelbare school. Precies de helft van de basisschoolleerlingen gaat op school niet naar het toilet. Bij de middelbare scholieren is dit 60%. In deze steekproef is er dus een verschil tussen basisschoolleerlingen en middelbare scholieren in het deel dat op school niet naar het toilet gaat.$$, 'inline'),
  ('7c932a1d-5feb-4c4f-b15c-7ec3a79c16f5', 'fff4b3ba-e78d-4e35-b469-60620a2ea4c3', $$vermoeden hygiëne en ziekmeldingen$$,
   $$wiskunde-a-havo-2024-ii-hygiene-op-school-context4.png$$,
   $$Veel ouders vermoeden dat een betere hygiëne op een school samengaat met een lager percentage ziekmeldingen onder de leerlingen van de betreffende school. Neem aan dat de hygiëne van een school uitgedrukt wordt in een score tussen 0 en 100 waarbij geldt: hoe hoger de score, hoe beter de hygiëne van de betreffende school.$$, 'inline'),
  ('ec96a98e-8b6c-43a4-a7f1-ae13f3f3b5f0', 'fff4b3ba-e78d-4e35-b469-60620a2ea4c3', $$stelling schoonmaakbudget$$,
   $$wiskunde-a-havo-2024-ii-hygiene-op-school-context5.png$$,
   $$De 630 leraren in de steekproef hebben gereageerd op de stelling of hun school over voldoende schoonmaakbudget beschikt om de hygiëne op school te kunnen waarborgen. Het resultaat staat in de tabel.$$, 'inline'),
  ('c32fd4ec-7c4a-4391-be71-f4917c747867', 'fff4b3ba-e78d-4e35-b469-60620a2ea4c3', $$tabel: reacties leraren$$,
   $$wiskunde-a-havo-2024-ii-hygiene-op-school-context6.png$$,
   $$tabel
stelling: het schoonmaakbudget is voldoende
reactie | weet niet | helemaal mee oneens | mee oneens | neutraal | mee eens | helemaal mee eens
percentage | 27 | 11 | 27 | 12 | 19 | 4$$, 'inline'),
  ('35430aad-7b5a-41f7-bae0-e02ce5c73a38', 'fff4b3ba-e78d-4e35-b469-60620a2ea4c3', $$conclusie in de media$$,
   $$wiskunde-a-havo-2024-ii-hygiene-op-school-context7.png$$,
   $$In de media werd naar aanleiding van dit onderzoek geconcludeerd dat ruim een derde van de leraren aangeeft dat het schoonmaakbudget te laag is om de hygiëne te kunnen waarborgen. Kennelijk had men hiervoor de twee reactiemogelijkheden ‘helemaal mee oneens’ (11%) en ‘mee oneens’ (27%) samengevoegd.$$, 'inline'),
  ('a8ad07a8-6c49-4aa1-9be4-c8cd29c7908f', 'fff4b3ba-e78d-4e35-b469-60620a2ea4c3', $$grafiek cumulatief percentage$$,
   $$wiskunde-a-havo-2024-ii-hygiene-op-school-context8.png$$,
   $$Een journalist maakte bij de gegevens uit de tabel een grafiek van het cumulatieve percentage. Zie de figuur.$$, 'inline'),
  ('3b34e587-68c6-40a9-8dc5-095a141b7e5b', 'fff4b3ba-e78d-4e35-b469-60620a2ea4c3', $$figuur: cumulatief percentage$$,
   $$wiskunde-a-havo-2024-ii-hygiene-op-school-context9.png$$,
   $$figuur
cumulatief percentage | reactiemogelijkheden: weet niet, helemaal mee oneens, mee oneens, neutraal, mee eens, helemaal mee eens
De manier waarop de reactiemogelijkheid ‘weet niet’ is opgenomen in de grafiek kan misleidend worden genoemd.$$, 'inline'),
  ('21e08866-1520-4a30-be81-61b3270e06e2', 'fff4b3ba-e78d-4e35-b469-60620a2ea4c3', $$uitwerkbijlage vraag 12$$,
   $$wiskunde-a-havo-2024-ii-hygiene-op-school-context10.png$$,
   $$12
Een puntenwolk die het vermoeden ondersteunt
ziekmeldingen (%) | score hygiëne op school$$, 'uitwerkbijlage'),
  ('2e50b00c-7a1a-4cd1-a47b-93d1b68cf935', 'de66e426-553e-44cc-a3cc-ee6cbd1ca154', $$inleiding: printabonnementen$$,
   $$wiskunde-a-havo-2024-ii-printabonnement-context1.png$$,
   $$Een copyshop biedt printabonnementen aan. Voor een vast bedrag per maand kun je een vast aantal pagina’s afdrukken. Wil je meer pagina’s afdrukken in die maand, dan moet je daarvoor extra betalen. Het aantal extra pagina’s dat je afdrukt, wordt bijgehouden door de copyshop. In deze opgave bedoelen we met ‘(afdruk)kosten’ telkens de kosten voor de klant, niet voor de copyshop.$$, 'inline'),
  ('3541963f-a6c0-4b08-bb1a-a64e2f822209', 'de66e426-553e-44cc-a3cc-ee6cbd1ca154', $$tabel: abonnementen$$,
   $$wiskunde-a-havo-2024-ii-printabonnement-context2.png$$,
   $$Er zijn verschillende abonnementen. Zie de tabel.
tabel
Naam abonnement | Print Gratis | Print Soms | Print Regelmatig
vast bedrag per maand | € 0 | € 3 | € 5
aantal gratis pagina’s per maand | 15 | 50 | 100
variabele kosten voor extra pagina’s | € 1 per 10 pagina’s | € 1 per 10 pagina’s | € 1 per 15 pagina’s
Bijvoorbeeld: als je het Print Soms-abonnement hebt en in een maand 51 pagina’s afdrukt, dan zijn de kosten voor die maand 3 + 1 = 4 euro. Ook 52 pagina’s kosten bij dit abonnement 4 euro.$$, 'inline'),
  ('ceebe2f1-e236-4d26-994f-97d937dcff46', 'de66e426-553e-44cc-a3cc-ee6cbd1ca154', $$35 pagina’s$$,
   $$wiskunde-a-havo-2024-ii-printabonnement-context3.png$$,
   $$Bij het afdrukken van 35 pagina’s in een maand zijn de kosten met een Print Gratis-abonnement lager dan met een Print Soms-abonnement.$$, 'inline'),
  ('89532d9d-9dac-4f20-a67a-870d6c425e26', 'de66e426-553e-44cc-a3cc-ee6cbd1ca154', $$Redouan en Jelle: 600 pagina’s per jaar$$,
   $$wiskunde-a-havo-2024-ii-printabonnement-context4.png$$,
   $$Redouan en Jelle hebben beiden het Print Soms-abonnement voor een jaar afgesloten. In dat jaar drukken ze elk 600 pagina’s af. Het is mogelijk dat Redouan voor dat jaar een ander bedrag kwijt is dan Jelle.$$, 'inline'),
  ('1d4ac394-6484-464c-ab44-9ede7a49c13e', 'de66e426-553e-44cc-a3cc-ee6cbd1ca154', $$nieuwe situatie: betalen per pagina$$,
   $$wiskunde-a-havo-2024-ii-printabonnement-context5.png$$,
   $$De copyshop besluit dat je voortaan het afdrukken van de extra pagina’s niet meer per 10 of 15 pagina’s betaalt, maar per stuk. Voor elk abonnement kunnen de kosten per afgedrukte pagina worden berekend met behulp van de variabele kosten uit de onderste rij van de tabel. Zo zijn bijvoorbeeld deze kosten bij het Print Gratis-abonnement 0,10 euro per pagina.$$, 'inline'),
  ('9ff83114-6435-4876-b223-448e0d6e2e99', 'de66e426-553e-44cc-a3cc-ee6cbd1ca154', $$figuur: inleiding$$,
   $$wiskunde-a-havo-2024-ii-printabonnement-context6.png$$,
   $$In de figuur zijn voor deze nieuwe situatie de afdrukkosten in een bepaalde maand voor de abonnementen Print Soms en Print Regelmatig weergegeven, afhankelijk van het aantal afgedrukte pagina’s. Ook is de grafiek weergegeven van een nieuw abonnement dat de copyshop aanbiedt: Print Vaak.$$, 'inline'),
  ('a49934b7-e72c-44e9-ae75-445c46c5d7f4', 'de66e426-553e-44cc-a3cc-ee6cbd1ca154', $$figuur: afdrukkosten$$,
   $$wiskunde-a-havo-2024-ii-printabonnement-context7.png$$,
   $$figuur
afdrukkosten (in €) | aantal afgedrukte pagina’s
Legenda: Print Vaak, Print Regelmatig, Print Soms$$, 'inline'),
  ('a2aac62a-def2-4b9e-8d8e-f30dfe811ef4', 'de66e426-553e-44cc-a3cc-ee6cbd1ca154', $$kolom Print Vaak$$,
   $$wiskunde-a-havo-2024-ii-printabonnement-context8.png$$,
   $$Met behulp van de beschrijving van de nieuwe situatie en de figuur, zou je aan de tabel (van de oude situatie) een kolom kunnen toevoegen voor het abonnement Print Vaak.$$, 'inline'),
  ('6634bd17-aec1-414c-818e-4c1a4c51a108', 'de66e426-553e-44cc-a3cc-ee6cbd1ca154', $$betekenis afdrukkosten en pagina’s$$,
   $$wiskunde-a-havo-2024-ii-printabonnement-context9.png$$,
   $$In de rest van deze opgave bedoelen we met ‘afdrukkosten’ de afdrukkosten per maand voor de klant en met ‘pagina’s’ afgedrukte pagina’s per maand.$$, 'inline'),
  ('5bddceab-c504-473e-9342-4b1ca7883ab8', 'de66e426-553e-44cc-a3cc-ee6cbd1ca154', $$formules 1 en 2: KS en KR$$,
   $$wiskunde-a-havo-2024-ii-printabonnement-context10.png$$,
   $$De afdrukkosten (in euro) voor de abonnementen Print Soms KS en Print Regelmati KR worden gegeven door de volgende formules:
KS = 3 als 0 ≤ p < 50; KS = 0,1p − 2 als p ≥ 50 (formule 1)
KR = 5 als 0 ≤ p < 100; KR = (1/15)p − 1⅔ als p ≥ 100 (formule 2)$$, 'inline'),
  ('37137b4f-3456-4cdc-babf-6211626dc9f7', 'de66e426-553e-44cc-a3cc-ee6cbd1ca154', $$betekenis p$$,
   $$wiskunde-a-havo-2024-ii-printabonnement-context11.png$$,
   $$Hierin is p het aantal pagina’s.$$, 'inline'),
  ('0a9f3bfb-403d-4cbc-953b-de8476901a3d', 'de66e426-553e-44cc-a3cc-ee6cbd1ca154', $$kleine aantallen pagina’s$$,
   $$wiskunde-a-havo-2024-ii-printabonnement-context12.png$$,
   $$Voor kleine aantallen pagina’s zijn de afdrukkosten bij het abonnement Print Soms lager dan bij Print Regelmatig.$$, 'inline'),
  ('2b77d2d7-eb0e-4e56-9a81-19a19ada580a', 'de66e426-553e-44cc-a3cc-ee6cbd1ca154', $$formule 3: kosten per pagina GR$$,
   $$wiskunde-a-havo-2024-ii-printabonnement-context13.png$$,
   $$Voor de afdrukkosten per pagina GR voor het abonnement Print Regelmatig geldt:
GR = KR/p (formule 3)
Hierin is p het aantal pagina’s, waarbij p minstens 100 is.$$, 'inline'),
  ('4e18e0ad-5180-4d59-a153-2d480a6c238a', 'de66e426-553e-44cc-a3cc-ee6cbd1ca154', $$formule 4$$,
   $$wiskunde-a-havo-2024-ii-printabonnement-context14.png$$,
   $$Formule 3 kan in de volgende vorm worden geschreven
GR = a − b/p (formule 4)
Hierin zijn a en b positieve getallen en p is het aantal pagina’s, waarbij p minstens 100 is.$$, 'inline'),
  ('ac407922-d270-4d4d-b728-1a55b9ce4f91', 'de66e426-553e-44cc-a3cc-ee6cbd1ca154', $$kosten per pagina G$$,
   $$wiskunde-a-havo-2024-ii-printabonnement-context15.png$$,
   $$De afdrukkosten per pagina G kunnen voor elk abonnement, als het aantal pagina’s groter is dan het aantal gratis pagina’s, beschreven worden met een formule van de vorm:$$, 'inline'),
  ('9a26f3fc-484c-40e3-aee6-33f66354973a', 'de66e426-553e-44cc-a3cc-ee6cbd1ca154', $$formule 5$$,
   $$wiskunde-a-havo-2024-ii-printabonnement-context16.png$$,
   $$G = c − d/p (formule 5)$$, 'inline'),
  ('f46a425a-89f8-4d13-93b4-1d0cec048861', 'de66e426-553e-44cc-a3cc-ee6cbd1ca154', $$c en d positief$$,
   $$wiskunde-a-havo-2024-ii-printabonnement-context17.png$$,
   $$Hierin zijn c en d positieve getallen.$$, 'inline'),
  ('0a1608ff-f239-4686-8311-286eb4721953', '65f62e0a-5490-49f7-8291-b8ade42d54f5', $$inleiding: prognoses CBS$$,
   $$wiskunde-a-havo-2024-ii-65-plussers-context1.png$$,
   $$Het CBS (Centraal Bureau voor de Statistiek) publiceerde eind 2018 een artikel met prognoses over het aantal inwoners in Nederland waaruit bleek dat dit aantal minstens tot 2030 zal blijven toenemen. Ook beweerde het CBS in dit artikel dat in 2030 bijna een kwart van de bevolking 65-plus (65 jaar of ouder) is. Zie de figuur. De gegevens gelden telkens op 31 december van het jaar.$$, 'inline'),
  ('df08d91e-0a7c-466e-bf5f-b1f1fcfd262e', '65f62e0a-5490-49f7-8291-b8ade42d54f5', $$figuur: bevolking naar leeftijd$$,
   $$wiskunde-a-havo-2024-ii-65-plussers-context2.png$$,
   $$figuur
Bevolking naar leeftijd op 31 december
aantal inwoners (miljoenen) | 2000, 2030
2000: 0 tot 65 jaar 13,6; 65 jaar of ouder 2,2
2030: 0 tot 65 jaar 13,8; 65 jaar of ouder 4,2
Legenda: 65 jaar of ouder, 0 tot 65 jaar$$, 'inline'),
  ('994fb8f0-7834-4e84-ad6c-d4fa601efa98', '65f62e0a-5490-49f7-8291-b8ade42d54f5', $$lineaire en exponentiële groei$$,
   $$wiskunde-a-havo-2024-ii-65-plussers-context3.png$$,
   $$Op basis van gegevens van de jaren 2000 tot en met 2018 en prognoses van 2019 tot en met 2030 verwacht men dat de totale bevolking in de periode 2000-2030 nagenoeg lineair zal groeien, terwijl het aantal 65-plussers exponentieel zal groeien. In deze opgave gaan we ervan uit dat deze lineaire en exponentiële groei zich beide na 2030 voortzetten.$$, 'inline');

insert into practice_questions (id, exercise_id, question_number, topics, keywords, question_summary, question_image_url, question_text, context_block_ids) values
  ('7ade4f7b-da64-40a1-8591-338dbf2c6375', 'c6e5de02-9b66-4503-b37c-9236dc65b1b8', 1,
   '[{"domain": "Algebra en tellen", "subdomain": "Rekenen"}]'::jsonb,
   '["procenten", "eenheden omrekenen", "gram naar kilogram", "aantal berekenen", "verschil berekenen", "afronden op miljoenen"]'::jsonb,
   $$Uit een totaalgewicht en een gemiddeld gewicht per stuk aantallen berekenen en het verschil bepalen.$$,
   $$wiskunde-a-havo-2024-ii-appels-met-peren-vergelijken-vraag1.png$$, $$3p 1 Bereken het verschil tussen deze twee aantallen. Geef je antwoord in een geheel aantal miljoenen.$$, array['babfb5f4-159b-4fc2-b121-631ab39b07e8', 'fb94c564-53a7-4bdf-be2b-b3eb82b7b706', '215b4681-a685-4612-8214-8c7f452ea88c']::uuid[]),
  ('30ea65a7-370f-4e38-8b15-e2d2bf590cac', 'c6e5de02-9b66-4503-b37c-9236dc65b1b8', 2,
   '[{"domain": "Algebra en tellen", "subdomain": "Rekenen"}]'::jsonb,
   '["procentuele toename", "procentuele afname", "terugrekenen naar 100%", "vermenigvuldigingsfactor", "oorspronkelijke waarde berekenen"]'::jsonb,
   $$Met gegeven procentuele toename en afname de oorspronkelijke waarden terugrekenen en optellen.$$,
   $$wiskunde-a-havo-2024-ii-appels-met-peren-vergelijken-vraag2.png$$, $$3p 2 Bereken dit totale gewicht. Geef je antwoord in een geheel aantal miljoenen kilogram.$$, array['fb94c564-53a7-4bdf-be2b-b3eb82b7b706', 'cc643190-5340-4277-b077-9d942cea4cbf']::uuid[]),
  ('70c4946a-a91f-4dd4-85ad-8b0c829ffa16', 'c6e5de02-9b66-4503-b37c-9236dc65b1b8', 3,
   '[{"domain": "Verbanden", "subdomain": "Grafieken, vergelijkingen en ongelijkheden"}, {"domain": "Statistiek", "subdomain": "Presentaties van data interpreteren en beoordelen"}]'::jsonb,
   '["grafiek interpreteren", "staafdiagram aflezen", "verhouding", "gemiddelde per eenheid", "redeneren zonder getallenvoorbeelden", "twee assen"]'::jsonb,
   $$Met een diagram met twee grootheden redeneren of een verhouding (opbrengst per oppervlakte) groter of kleiner wordt.$$,
   $$wiskunde-a-havo-2024-ii-appels-met-peren-vergelijken-vraag3.png$$, $$3p 3 Beredeneer, zonder gebruik te maken van getallenvoorbeelden, met behulp van figuur 2 of de gemiddelde perenoogst in miljoen kg per hectare in 2008 groter of kleiner is dan in 2003.$$, array['a1485707-a9a8-46f2-a6c7-ad7682f08e8a', 'cf225ee3-ab4c-4a8e-9b1a-1938ef4f4a30']::uuid[]),
  ('2a87aa7e-0641-4bda-b746-2b15b5c65d5e', 'c6e5de02-9b66-4503-b37c-9236dc65b1b8', 4,
   '[{"domain": "Verbanden", "subdomain": "Lineaire verbanden"}, {"domain": "Verbanden", "subdomain": "Grafieken, vergelijkingen en ongelijkheden"}]'::jsonb,
   '["lineaire formule opstellen", "richtingscoëfficiënt", "snijpunt van twee lijnen", "lineaire ongelijkheid", "tabel", "jaartal bepalen"]'::jsonb,
   $$Een lineaire formule opstellen uit twee tabelwaarden en bepalen wanneer een andere lineaire formule deze voor het eerst overtreft.$$,
   $$wiskunde-a-havo-2024-ii-appels-met-peren-vergelijken-vraag4.png$$, $$5p 4 Bereken in welk jaar de perenteeltoppervlakte voor het eerst groter is dan de appelteeltoppervlakte.$$, array['c06cea1a-9fea-4dc2-ab83-443426a6407a', '573ae60e-89ee-4a9b-86cd-d397e54bbee2']::uuid[]),
  ('52544e0c-0758-419a-8cf9-8c569469b562', 'c6e5de02-9b66-4503-b37c-9236dc65b1b8', 5,
   '[{"domain": "Verbanden", "subdomain": "Exponentiële verbanden"}]'::jsonb,
   '["groeifactor", "groeifactor omrekenen", "groeipercentage berekenen", "exponentiële afname", "machtswortel", "afnamepercentage per jaar"]'::jsonb,
   $$Een afnamepercentage per vijf jaar omrekenen naar een afnamepercentage per jaar.$$,
   $$wiskunde-a-havo-2024-ii-appels-met-peren-vergelijken-vraag5.png$$, $$4p 5 Bereken met hoeveel procent de appelteeltoppervlakte dan per jaar afneemt. Geef je antwoord in één decimaal.$$, array['bf82310e-0572-44ab-aed2-fb877247cfa4']::uuid[]),
  ('c1d4fdca-2bac-4d6c-94bb-395e66878b93', 'f81929e4-074d-45f4-9b8e-ba91c6a13168', 6,
   '[{"domain": "Verbanden", "subdomain": "Formules met één of meer variabelen"}, {"domain": "Algebra en tellen", "subdomain": "Rekenen"}]'::jsonb,
   '["verhoudingen", "substitutie in formule", "evenredigheid", "steekproef", "afronden op honderdtallen", "vangen-hervangen"]'::jsonb,
   $$Met een verhoudingsformule uit steekproefgegevens een populatiegrootte schatten.$$,
   $$wiskunde-a-havo-2024-ii-vangen-hervangen-vraag6.png$$, $$3p 6 Bereken met behulp van formule 1 hoeveel vissen er in het meer zijn. Geef je antwoord in een geheel honderdtal.$$, array['4620c85e-9bd8-415f-8231-f1a7fe686eda', '6e2bfb47-0c91-4ec2-bc2a-1ffb667f2027', '8d9817b5-7440-4760-9283-95d1e6dda3de', '1408b486-ac08-4d3c-98da-8582cd5cb2e8', '4dd8289f-274e-4d19-8421-28ade2d4a829']::uuid[]),
  ('60c82311-8b0c-4fca-b720-0649069e2001', 'f81929e4-074d-45f4-9b8e-ba91c6a13168', 7,
   '[{"domain": "Verbanden", "subdomain": "Formules met één of meer variabelen"}, {"domain": "Algebra en tellen", "subdomain": "Algebra"}]'::jsonb,
   '["vergelijking opstellen", "substitutie in formule", "breuk met variabele", "verschil van twee uitkomsten", "vergelijking oplossen", "inklemmen"]'::jsonb,
   $$Met een formule met een variabele in de noemer een vergelijking opstellen voor een gegeven verschil en die oplossen.$$,
   $$wiskunde-a-havo-2024-ii-vangen-hervangen-vraag7.png$$, $$4p 7 Bereken het aantal gemerkte vissen in de steekproef van Adri.$$, array['1408b486-ac08-4d3c-98da-8582cd5cb2e8', '440f71ed-4e18-4a26-bf76-1bc16c0ed893', 'f027f0fd-d4ea-4b0c-891b-ae4bade9ae9f']::uuid[]),
  ('8a7d1d45-278f-4c65-863c-73e3e6ec42c5', 'f81929e4-074d-45f4-9b8e-ba91c6a13168', 8,
   '[{"domain": "Verbanden", "subdomain": "Formules met één of meer variabelen"}]'::jsonb,
   '["delen door nul", "noemer nul", "formule interpreteren", "randgeval", "breuk", "steekproef"]'::jsonb,
   $$Uitleggen in welke situatie een formule met een breuk geen uitkomst geeft omdat de noemer nul is.$$,
   $$wiskunde-a-havo-2024-ii-vangen-hervangen-vraag8.png$$, $$2p 8 Beschrijf deze situatie en leg uit waarom het in die situatie niet lukt om met formule 2 het aantal vissen in het meer te schatten.$$, array['8d9817b5-7440-4760-9283-95d1e6dda3de', '1408b486-ac08-4d3c-98da-8582cd5cb2e8', '440f71ed-4e18-4a26-bf76-1bc16c0ed893', 'f027f0fd-d4ea-4b0c-891b-ae4bade9ae9f', 'b74349d7-9e0c-4807-b5c3-de6033d9f995']::uuid[]),
  ('38ec614f-3079-4596-a587-f57079940f5d', 'f81929e4-074d-45f4-9b8e-ba91c6a13168', 9,
   '[{"domain": "Verbanden", "subdomain": "Grafieken, vergelijkingen en ongelijkheden"}, {"domain": "Verbanden", "subdomain": "Formules met één of meer variabelen"}]'::jsonb,
   '["ongelijkheid oplossen", "twee formules vergelijken", "substitutie in formule", "verschil van formules", "tabel van de GR", "gehele oplossingen"]'::jsonb,
   $$Bepalen voor welke gehele waarden het verschil tussen twee formules groter is dan een gegeven getal.$$,
   $$wiskunde-a-havo-2024-ii-vangen-hervangen-vraag9.png$$, $$4p 9 Bereken bij welke aantallen gemerkte vissen in een tweede steekproef de schatting volgens formule 2 meer dan 100 hoger is dan de schatting volgens formule 3.$$, array['1408b486-ac08-4d3c-98da-8582cd5cb2e8', '440f71ed-4e18-4a26-bf76-1bc16c0ed893', 'f027f0fd-d4ea-4b0c-891b-ae4bade9ae9f', '2db3f9d7-2fac-4e4e-8ff2-1a51d4c5a99a']::uuid[]),
  ('8125c73e-ef13-484c-8869-a6f77e8af780', 'fff4b3ba-e78d-4e35-b469-60620a2ea4c3', 10,
   '[{"domain": "Statistiek", "subdomain": "Statistische uitspraken doen"}]'::jsonb,
   '["betrouwbaarheidsinterval", "95%-betrouwbaarheidsinterval", "steekproefproportie", "populatieproportie", "formuleblad", "standaardfout"]'::jsonb,
   $$Een 95%-betrouwbaarheidsinterval voor een populatiepercentage berekenen uit een steekproefproportie.$$,
   $$wiskunde-a-havo-2024-ii-hygiene-op-school-vraag10.png$$, $$4p 10 Bereken het 95%-betrouwbaarheidsinterval voor het percentage Nederlandse leerlingen tussen de 5 en 16 jaar oud, waarvoor het bovenstaande geldt. Geef de percentages in je antwoord in gehelen.$$, array['9172e2e2-f4e3-406b-b11e-e280e99cd2ff', 'bd3a54b4-a783-4952-9409-df240ee5ea9b']::uuid[]),
  ('d9701299-fe93-4330-bbe7-1f9fefd645f6', 'fff4b3ba-e78d-4e35-b469-60620a2ea4c3', 11,
   '[{"domain": "Statistiek", "subdomain": "Statistische uitspraken doen"}]'::jsonb,
   '["effectgrootte", "verschil tussen proporties", "formuleblad", "gering, middelmatig of groot", "steekproefproportie", "twee groepen vergelijken"]'::jsonb,
   $$Met de formule voor het verschil van twee proporties beoordelen of een verschil gering, middelmatig of groot is.$$,
   $$wiskunde-a-havo-2024-ii-hygiene-op-school-vraag11.png$$, $$4p 11 Onderzoek met behulp van het formuleblad of dat verschil groot, middelmatig of gering is.$$, array['7f479665-a33a-48c2-a415-b69bf11b9d44']::uuid[]),
  ('e0070da2-bb1b-474d-83da-a84e0af4592f', 'fff4b3ba-e78d-4e35-b469-60620a2ea4c3', 12,
   '[{"domain": "Statistiek", "subdomain": "Data verwerken"}, {"domain": "Statistiek", "subdomain": "Statistische uitspraken doen"}]'::jsonb,
   '["puntenwolk", "negatief verband", "samenhang", "schets maken", "twee kwantitatieve variabelen"]'::jsonb,
   $$Een puntenwolk schetsen die een negatief verband tussen twee variabelen weergeeft.$$,
   $$wiskunde-a-havo-2024-ii-hygiene-op-school-vraag12.png$$, $$2p 12 Geef op de uitwerkbijlage een schets van een mogelijke puntenwolk die het vermoeden ondersteunt dat een betere hygiëne samengaat met een lager percentage ziekmeldingen.$$, array['7c932a1d-5feb-4c4f-b15c-7ec3a79c16f5', '21e08866-1520-4a30-be81-61b3270e06e2']::uuid[]),
  ('c9831eac-43d9-41f6-a65a-8f6009a190f0', 'fff4b3ba-e78d-4e35-b469-60620a2ea4c3', 13,
   '[{"domain": "Statistiek", "subdomain": "Presentaties van data interpreteren en beoordelen"}]'::jsonb,
   '["ordinale variabele", "kwalitatieve variabele", "gemiddelde", "meetniveau", "centrummaat", "type variabele"]'::jsonb,
   $$Uitleggen of een gemiddelde zinvol is bij een ordinale kwalitatieve variabele.$$,
   $$wiskunde-a-havo-2024-ii-hygiene-op-school-vraag13.png$$, $$2p 13 Had men op basis van deze tabel ook een uitspraak over het gemiddelde van de lerarenreacties kunnen doen? Licht je antwoord toe.$$, array['ec96a98e-8b6c-43a4-a7f1-ae13f3f3b5f0', 'c32fd4ec-7c4a-4391-be71-f4917c747867', '35430aad-7b5a-41f7-bae0-e02ce5c73a38']::uuid[]),
  ('444b25cc-76c6-44ff-a6c4-d82b031bd3ce', 'fff4b3ba-e78d-4e35-b469-60620a2ea4c3', 14,
   '[{"domain": "Statistiek", "subdomain": "Presentaties van data interpreteren en beoordelen"}, {"domain": "Statistiek", "subdomain": "Data verwerken"}]'::jsonb,
   '["cumulatief percentage", "misleidende grafiek", "ordinale volgorde", "categorie weglaten", "grafiek beoordelen", "somfrequentiepolygoon"]'::jsonb,
   $$Beoordelen waarom een cumulatieve grafiek misleidend is en een betere verwerking van een categorie voorstellen.$$,
   $$wiskunde-a-havo-2024-ii-hygiene-op-school-vraag14.png$$, $$3p 14 Leg uit waarom deze manier misleidend kan worden genoemd en geef aan wat een betere manier is om met deze reactiemogelijkheid om te gaan bij het maken van zo’n grafiek.$$, array['c32fd4ec-7c4a-4391-be71-f4917c747867', 'a8ad07a8-6c49-4aa1-9be4-c8cd29c7908f', '3b34e587-68c6-40a9-8dc5-095a141b7e5b']::uuid[]),
  ('2c88b3c0-f4f8-43a9-ba4c-82fa6896d58e', 'de66e426-553e-44cc-a3cc-ee6cbd1ca154', 15,
   '[{"domain": "Algebra en tellen", "subdomain": "Rekenen"}, {"domain": "Verbanden", "subdomain": "Tabellen"}]'::jsonb,
   '["procentuele afname", "procent lager", "tabel aflezen", "kosten berekenen", "afronden op hele procenten"]'::jsonb,
   $$Met gegevens uit een tabel twee bedragen berekenen en het procentuele verschil bepalen.$$,
   $$wiskunde-a-havo-2024-ii-printabonnement-vraag15.png$$, $$3p 15 Bereken hoeveel procent lager. Geef je antwoord in hele procenten.$$, array['2e50b00c-7a1a-4cd1-a47b-93d1b68cf935', '3541963f-a6c0-4b08-bb1a-a64e2f822209', 'ceebe2f1-e236-4d26-994f-97d937dcff46']::uuid[]),
  ('73214ba6-9579-4f97-8b51-a6d469f8ef33', 'de66e426-553e-44cc-a3cc-ee6cbd1ca154', 16,
   '[{"domain": "Algebra en tellen", "subdomain": "Rekenen"}, {"domain": "Verbanden", "subdomain": "Tabellen"}]'::jsonb,
   '["maximaal verschil", "afronden naar boven", "trapfunctie", "tabel aflezen", "kosten per maand", "verdeling over maanden"]'::jsonb,
   $$Bij een tarief per begonnen blok pagina’s het maximaal mogelijke kostenverschil over een jaar berekenen.$$,
   $$wiskunde-a-havo-2024-ii-printabonnement-vraag16.png$$, $$4p 16 Bereken het maximale verschil in euro’s dat mogelijk is.$$, array['3541963f-a6c0-4b08-bb1a-a64e2f822209', '89532d9d-9dac-4f20-a67a-870d6c425e26']::uuid[]),
  ('9bed620b-4cd0-47d2-98ff-0e2c1fa22e12', 'de66e426-553e-44cc-a3cc-ee6cbd1ca154', 17,
   '[{"domain": "Verbanden", "subdomain": "Lineaire verbanden"}, {"domain": "Verbanden", "subdomain": "Grafieken, vergelijkingen en ongelijkheden"}]'::jsonb,
